import {dayKey,shiftDay} from './energy-spacing.mjs';
export function renderEnergyCalendar(host,{store,rows,plan,lab,begin,kind='diagnostic'}){
 const today=dayKey(),state=store.snapshot(),schedule=store.schedule(today);let month=today.slice(0,7),selected=today;
 const root=document.createElement('section');root.className='energy-calendar';host.append(root);
 function render(){const streak=store.streak(today);root.replaceChildren();const el=(tag,text,parent=root)=>{const e=document.createElement(tag);e.textContent=text;parent.append(e);return e;};
 el('h3',kind==='repair'?'Calendario de reparaciones':'Calendario y práctica diaria');el('p','Repasos a 1, 3, 7, 14 y 30 días. Un resultado con errores o pistas vuelve a 1 día; repetir el mismo día no amplía el intervalo. Las fechas usan el día local de este navegador.');
 const progress=state.days[today]?.count||0;el('strong',`Hoy: ${progress}/${state.goal} retos · Racha: ${streak.current} días · Mejor: ${streak.best}`);el('p',kind==='repair'?'Cada taller completado cuenta una vez, incluso con pistas. Cumplir la meta no elimina averías pendientes. La meta nueva afecta hoy y los próximos días; el pasado conserva su meta.':'Cada diagnóstico completado cuenta una vez, incluso con pistas; en examen solo cuentan los casos correctos. Cumplir la meta no elimina averías pendientes. La meta nueva afecta hoy y los próximos días; el pasado conserva su meta.');
 const label=el('label','Meta diaria '),input=el('input','',label);input.type='number';input.min=1;input.max=10;input.value=state.goal;input.dataset.energyGoal='';const save=el('button','Guardar meta');save.onclick=()=>{const n=Number(input.value);if(!Number.isInteger(n)||n<1||n>10){msg.hidden=false;msg.textContent='Elige una meta entera entre 1 y 10.';return;}store.setGoal(n);Object.assign(state,store.snapshot());render();};const msg=el('p','');msg.setAttribute('role','status');msg.hidden=true;
 if(store.warning())el('p',store.warning());
 const nav=el('div','');for(const [text,delta]of [['Mes anterior',-1],['Mes siguiente',1]]){const b=el('button',text,nav);b.onclick=()=>{const d=new Date(month+'-01T12:00:00');d.setMonth(d.getMonth()+delta);month=dayKey(d).slice(0,7);render();};}const now=el('button','Hoy',nav);now.onclick=()=>{month=today.slice(0,7);selected=today;render();};
 el('h4',new Date(month+'-01T12:00:00').toLocaleDateString('es-CO',{month:'long',year:'numeric'}));const grid=el('div','');grid.className='energy-days';for(const name of ['L','M','X','J','V','S','D'])el('span',name,grid);
 const first=month+'-01',offset=(new Date(first+'T12:00:00').getDay()+6)%7;for(let i=0;i<offset;i++)el('span','',grid);
 for(let d=first;d.slice(0,7)===month;d=shiftDay(d,1)){const date=d,entry=state.days[d],due=schedule.filter(s=>(s.due<today?today:s.due)===d).length;const b=el('button',Number(d.slice(-2))+(entry?.count>=entry?.goal?' ✓':'')+(due?' •':''),grid);b.setAttribute('aria-label',d+' · '+(entry?.count||0)+' retos · '+due+' repasos previstos');b.setAttribute('aria-pressed',String(selected===d));b.onclick=()=>{selected=date;render();};}
 el('p','✓ Meta cumplida · • Repasos previstos. Los vencidos se reúnen en hoy; el futuro se recalcula al practicar.');el('h4','Repasos del '+selected);const day=state.days[selected];el('p',day?day.count+' retos completados · meta '+day.goal:'Sin práctica registrada.');
 const due=schedule.filter(s=>(s.due<today?today:s.due)===selected).sort((a,b)=>plan.findIndex(p=>p.lab===a.lab&&p.fault===a.fault)-plan.findIndex(p=>p.lab===b.lab&&p.fault===b.fault));if(!due.length)el('p','No hay repasos programados para esta fecha.');for(const item of due){el('p',item.label+' · '+(item.new?'Primera práctica':item.due<today?'Vencido desde '+item.due:'Intervalo de '+item.interval+' días'));const adaptive=plan.find(p=>p.lab===item.lab&&p.fault===item.fault);if(kind==='repair'||item.lab===lab){const b=el('button','Practicar '+item.label);b.dataset.spacedReview=item.fault;b.onclick=()=>begin(adaptive);}else{const a=el('a','Abrir laboratorio para repasar');a.href='../concepts/index.html?id='+item.lab+'&review='+item.fault;a.target='_top';a.className='energy-review-link';}}
 el('h4','Cómo vas mejorando');for(const item of schedule){const relevant=rows.filter(r=>r.lab===item.lab&&r.faults.includes(item.fault));if(!relevant.length)continue;const avg=a=>Math.round(a.reduce((n,r)=>n+r.score,0)/a.length);el('p',item.label+' · '+relevant.length+' retos · '+(relevant.length>=6?'Primeros 3: '+avg(relevant.slice(0,3))+'/100 → últimos 3: '+avg(relevant.slice(-3))+'/100.':'Media: '+avg(relevant)+'/100. Faltan '+(6-relevant.length)+' retos para comparar grupos separados.')+' Próximo repaso: '+item.due+'.');}el('p','La comparación usa los '+(kind==='repair'?100:200)+' resultados conservados y puede mezclar dificultades; no es una prueba de dominio. El calendario conserva sus logros aunque rote ese historial.');
 }
 render();
}
